int 화면글(int сопственик_објект,int идентификатор_VALUE,const uint32_t *податоци,unsigned ставка_COUNT){графичка_контрола_статус *너비값=елемент_VALUE(сопственик_објект,идентификатор_VALUE);if(!너비값)return -9;if(ставка_COUNT>127)return -22;for(unsigned 순번=0;순번<ставка_COUNT;순번++){unsigned знак_кодирање=податоци[순번];if(знак_кодирање>0x10ffff||(знак_кодирање>=0xd800&&знак_кодирање<=0xdfff))return -22;}for(unsigned 순번=0;순번<ставка_COUNT;순번++)너비값->Текст[순번]=податоци[순번];너비값->должина_VALUE=ставка_COUNT;if(표시됨(сопственик_објект,너비값))табла_Терминал(3);return 0;}
